mapper.select:
SELECT c.id, c.customer_name, c.mobile, c.status, c.intent_level, c.budget_min, c.budget_max, c.region, c.house_type, c.heat_score, c.latest_follow_time, c.next_follow_time, advisor.nickname AS advisor_name, manager.nickname AS manager_name FROM crm_customer c LEFT JOIN sys_user advisor ON c.advisor_id = advisor.id LEFT JOIN sys_user manager ON c.manager_id = manager.id WHERE c.deleted = 0
AND (c.customer_name LIKE CONCAT('%', #{query.keyword}, '%') OR c.mobile LIKE CONCAT('%', #{query.keyword}, '%'))
AND c.status = #{query.status}
AND c.advisor_id = #{query.advisorId}
AND c.manager_id = #{query.managerId}
AND c.dept_id = #{query.deptId}
AND c.heat_score >= #{query.minHeatScore}
AND c.heat_score <= #{query.maxHeatScore}
ORDER BY c.created_at DESC
